'use strict';
// ======================================================================
//  Som (sintetizado, sem arquivos)
// ======================================================================
const SND_DATA={"woodH0": "data:audio/mpeg;base64,", "woodH1": "data:audio/mpeg;base64,", "woodM": "data:audio/mpeg;base64,", "mine0": "data:audio/mpeg;base64,", "mine1": "data:audio/mpeg;base64,", "mine2": "data:audio/mpeg;base64,", "punchM": "data:audio/mpeg;base64,", "punchH": "data:audio/mpeg;base64,", "soft0": "data:audio/mpeg;base64,", "softH": "data:audio/mpeg;base64,", "grass0": "data:audio/mpeg;base64,", "grass1": "data:audio/mpeg;base64,", "grass2": "data:audio/mpeg;base64,", "stepWood": "data:audio/mpeg;base64,", "plank": "data:audio/mpeg;base64,", "metal": "data:audio/mpeg;base64,", "generic": "data:audio/mpeg;base64,"};
let AC=null,noiseBuf=null;const SND={};let sndLoading=false;
function loadSounds(){if(!AC||sndLoading)return;sndLoading=true;for(const k in SND_DATA){try{const bin=atob(SND_DATA[k].split(',')[1]);const buf=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)buf[i]=bin.charCodeAt(i);
  AC.decodeAudioData(buf.buffer,ab=>{SND[k]=ab;},()=>{});}catch(e){}}}
function playS(names,vol,rate){if(!AC)return false;const list=names.filter(n=>SND[n]);if(!list.length)return false;try{const src=AC.createBufferSource();src.buffer=SND[list[Math.floor(Math.random()*list.length)]];
  src.playbackRate.value=(rate||1)*(0.92+Math.random()*0.16);const g=AC.createGain();g.gain.value=vol;src.connect(g);g.connect(AC.destination);src.start();return true;}catch(e){return false;}}
function playSample(type,o){const v=o.vol==null?1:o.vol;
  if(type==='tree')return o.good?playS(['woodH0','woodH1'],0.9*v):playS(['woodM'],0.7*v);
  if(type==='rock')return o.good?playS(['mine0','mine1','mine2'],0.85*v):playS(['generic'],0.75*v,0.8);
  if(type==='scrap')return playS(['metal'],0.7*v);
  if(type==='bush')return playS(['soft0','softH'],0.6*v);
  if(type==='flesh')return playS(['punchM','punchH'],0.7*v);
  if(type==='place')return playS(['plank'],0.8*v);
  if(type==='step')return o.wood?playS(['stepWood'],0.35*v):playS(['grass0','grass1','grass2'],0.3*v);
  return false;}
function audioInit(){if(AC){if(AC.state==='suspended')AC.resume();return;}try{AC=new (window.AudioContext||window.webkitAudioContext)();setTimeout(loadSounds,0);const n=AC.sampleRate*0.5;noiseBuf=AC.createBuffer(1,n,AC.sampleRate);const d=noiseBuf.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;}catch(e){AC=null;}}
function sfx(type,opt){opt=opt||{};if(!AC)return;if(playSample(type,opt))return;try{const t=AC.currentTime;const out=AC.createGain();out.gain.value=opt.vol==null?1:opt.vol;out.connect(AC.destination);
  const tone=(f1,f2,dur,wave,vol,delay)=>{const o=AC.createOscillator();const g=AC.createGain();o.type=wave||'sine';o.frequency.setValueAtTime(f1,t+(delay||0));o.frequency.exponentialRampToValueAtTime(f2,t+(delay||0)+dur);g.gain.setValueAtTime(vol,t+(delay||0));g.gain.exponentialRampToValueAtTime(0.001,t+(delay||0)+dur);o.connect(g);g.connect(out);o.start(t+(delay||0));o.stop(t+(delay||0)+dur+0.02);};
  const burst=(freq,q,dur,vol,type2)=>{const s=AC.createBufferSource();s.buffer=noiseBuf;const f=AC.createBiquadFilter();f.type=type2||'lowpass';f.frequency.value=freq;f.Q.value=q;const g=AC.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);s.connect(f);f.connect(g);g.connect(out);s.start(t);s.stop(t+dur+0.02);};
  if(type==='tree'){burst(700,1,0.12,0.5);tone(160,90,0.1,'triangle',0.25);}
  else if(type==='rock'||type==='scrap'){burst(2400,2,0.09,0.35,'bandpass');tone(420,300,0.06,'square',0.05);}
  else if(type==='bush'){burst(3000,0.5,0.12,0.18,'highpass');}
  else if(type==='swing'){burst(1200,0.7,0.12,0.06,'bandpass');}
  else if(type==='pick'){tone(660,990,0.08,'sine',0.12);}
  else if(type==='craft'){tone(520,520,0.07,'triangle',0.12);tone(780,780,0.1,'triangle',0.12,0.08);}
  else if(type==='place'){burst(300,1,0.15,0.4);tone(110,70,0.15,'sine',0.25);}
  else if(type==='hurt'){tone(220,90,0.22,'sawtooth',0.12);}
  else if(type==='flesh'){burst(500,3,0.1,0.4,'bandpass');}
  else if(type==='step'){burst(420,0.9,0.06,0.09);}
  else if(type==='grunt'){burst(320,4,0.22,0.5,'bandpass');tone(95,70,0.22,'sawtooth',0.12);tone(140,90,0.12,'sawtooth',0.06,0.12);}
  else if(type==='squeal'){tone(700,1100,0.25,'sawtooth',0.07);burst(1400,3,0.2,0.2,'bandpass');}
  else if(type==='growl'){const o=AC.createOscillator(),g=AC.createGain(),l=AC.createOscillator(),lg=AC.createGain();o.type='sawtooth';o.frequency.value=85;l.frequency.value=24;lg.gain.value=0.06;l.connect(lg);lg.connect(g.gain);g.gain.setValueAtTime(0.08,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.7);const f=AC.createBiquadFilter();f.type='lowpass';f.frequency.value=600;o.connect(f);f.connect(g);g.connect(out);o.start(t);l.start(t);o.stop(t+0.75);l.stop(t+0.75);}
  else if(type==='howl'){const o=AC.createOscillator(),g=AC.createGain(),v=AC.createOscillator(),vg=AC.createGain();o.type='sine';o.frequency.setValueAtTime(330,t);o.frequency.linearRampToValueAtTime(620,t+0.7);o.frequency.linearRampToValueAtTime(560,t+1.8);o.frequency.linearRampToValueAtTime(400,t+2.6);
    v.frequency.value=5;vg.gain.value=9;v.connect(vg);vg.connect(o.frequency);g.gain.setValueAtTime(0.001,t);g.gain.linearRampToValueAtTime(0.12,t+0.4);g.gain.linearRampToValueAtTime(0.1,t+2);g.gain.exponentialRampToValueAtTime(0.001,t+2.7);o.connect(g);g.connect(out);o.start(t);v.start(t);o.stop(t+2.8);v.stop(t+2.8);}
  else if(type==='yelp'){tone(900,500,0.18,'triangle',0.12);}
  else if(type==='join'){tone(440,660,0.12,'sine',0.1);tone(660,880,0.14,'sine',0.1,0.12);}
  else if(type==='done'){tone(520,520,0.09,'triangle',0.14);tone(660,660,0.09,'triangle',0.14,0.1);tone(880,880,0.16,'triangle',0.14,0.2);}
  }catch(e){}}
